const grid=document.querySelector('#listingGrid');let active='jobs';
function render(kind){active=kind;grid.innerHTML=listings[kind].map(x=>`<a class="listing" href="${x[6]}" target="_blank" rel="noopener noreferrer"><div class="listing-top"><div class="listing-icon" style="background:${x[5]}20;color:${x[5]}">${x[0]}</div><span class="listing-tag">${kind==='jobs'?'каталог':kind==='events'?'сейчас':kind==='grants'?'проверено':'живые данные'}</span></div><h3>${x[1]}</h3><p>${x[2]}<br>${x[3]}</p><div class="listing-bottom"><b>${x[4]}</b><span>Открыть →</span></div></a>`).join('')}
document.querySelectorAll('.feed-tabs button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.feed-tabs button').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-selected','false')});btn.classList.add('active');btn.setAttribute('aria-selected','true');render(btn.dataset.tab)}));render(active);
document.querySelector('#applyFilters').addEventListener('click',()=>{const city=document.querySelector('#city').value;const specialty=document.querySelector('#specialty').value;document.querySelector('#filterResult').textContent=`Подобрали возможности для направления «${specialty}» в городе ${city}`;document.querySelector('#feed').scrollIntoView({behavior:'smooth',block:'start'})});
